  const rng = (lo, hi, u, fmt) => `${fmt(xg(hi, u))}–${fmt(xg(lo, u))}`.replace(/ m–/, '–').replace(/ km–/, '–');
  const x5um = xg(5, 5);
  // RB-011 §3.3 practical table (rb-011:320-322) and §3.4 mass split (rb-011:337-339) — verbatim paper cells
