// ---------------------------------------------------------------------------
// write / --check
// ---------------------------------------------------------------------------
const NAMES = Object.keys(out).sort();
if (NAMES.length !== 9) throw new Error('expected nine diagrams, got ' + NAMES.length);
const check = process.argv.includes('--check');
const diffs = [];
for (const name of NAMES) {
  let cur = null;
  try { cur = readFileSync(D + name, 'utf8'); } catch { cur = null; }
  if (check) {
    if (cur !== out[name]) diffs.push(name);
  } else if (cur !== out[name]) {
    mkdirSync(D, { recursive: true });
    writeFileSync(D + name, out[name]);
    console.log('wrote', name, out[name].length, 'bytes');
  } else {
    console.log('unchanged', name);
  }
}
if (check) {
  if (diffs.length) {
    console.error('generate-diagrams --check: committed SVG differs from generator output:\n  ' + diffs.join('\n  ') + '\nRun: node scripts/generate-diagrams.mjs');
    process.exit(1);
  }
  console.log('generate-diagrams --check: all nine static/diagrams/*.svg match the generator');
}
